(function () {
  var HTML = "<div>\n<section class=\"hero\"><div class=\"ic hero-ic\">\n<div><p class=\"kicker\">АКТИВЫ, ПРОЦЕНТЫ, ТЕСТЫ<\/p><h1>Что видишь, то и во флаконе.<\/h1><p class=\"alt\">Активы каждого продукта и их проценты указаны на коробке. 4 ключевых актива указаны и на флаконе. Здесь можно посмотреть, что они делают и как их тестировали.<\/p><\/div>\n<div><div class=\"ist\"><div><b>0<\/b><span>несоответствующих результатов<\/span><\/div><div><b>35<\/b><span>лабораторных отчетов<\/span><\/div><div><b>5<\/b><span>видов тестов<\/span><\/div><\/div><div class=\"gv\"><p>Каждый продукт прошел 5 анализов во внешних лабораториях.<\/p><ul class=\"anl\"><li>Дерматологический тест<\/li><li>Микробиологическое качество<\/li><li>Система консервации<\/li><li>Стабильность<\/li><li>Тяжелые металлы<\/li><\/ul><p>В 48-часовом дерматологическом тесте с добровольцами с чувствительной кожей каждый из 7 продуктов вошел в класс «не раздражающий».<\/p>\n<p><a class=\"ok\" href=\"/ru/pages/test-sonuclarimiz\">Смотреть результаты тестов<\/a><\/p><\/div><\/div>\n<\/div><\/section>\n<section class=\"sec\" id=\"sec\"><div class=\"ic\"><h2>Что беспокоит тебя больше всего?<\/h2><p class=\"sec-alt\">Выбери одно. Посмотри подходящий тебе продукт и активы в нем.<\/p><\/div><\/section>\n<div class=\"cipler\"><div class=\"ic cip-ic\" role=\"tablist\" aria-label=\"Продукт по проблеме\"><button class=\"cip\" role=\"tab\" id=\"t-breakout\" data-k=\"breakout\" aria-controls=\"p-breakout\" aria-selected=\"false\" style=\"--r:#FF5442\"><i><\/i>Кожа, склонная к акне<\/button><button class=\"cip\" role=\"tab\" id=\"t-calm\" data-k=\"calm\" aria-controls=\"p-calm\" aria-selected=\"false\" style=\"--r:#5FD6DF\"><i><\/i>Покраснение<\/button><button class=\"cip\" role=\"tab\" id=\"t-juice\" data-k=\"juice\" aria-controls=\"p-juice\" aria-selected=\"false\" style=\"--r:#FAA827\"><i><\/i>Тусклость<\/button><button class=\"cip\" role=\"tab\" id=\"t-spot\" data-k=\"spot\" aria-controls=\"p-spot\" aria-selected=\"false\" style=\"--r:#3395DA\"><i><\/i>Пятна<\/button><button class=\"cip\" role=\"tab\" id=\"t-time\" data-k=\"time\" aria-controls=\"p-time\" aria-selected=\"false\" style=\"--r:#8970C9\"><i><\/i>Морщины<\/button><button class=\"cip\" role=\"tab\" id=\"t-reborn\" data-k=\"reborn\" aria-controls=\"p-reborn\" aria-selected=\"false\" style=\"--r:#33302D\"><i><\/i>Поры и текстура<\/button><button class=\"cip\" role=\"tab\" id=\"t-pore\" data-k=\"pore\" aria-controls=\"p-pore\" aria-selected=\"false\" style=\"--r:#33302D\"><i><\/i>Поры и матовость<\/button><\/div><\/div>\n<section class=\"panel\" id=\"p-breakout\" role=\"tabpanel\" aria-labelledby=\"t-breakout\" style=\"--k:#BF3D44\"><div class=\"ic pn\"><div class=\"ur\"><img class=\"ur-g\" loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/866397ff3368.jpg\" alt=\"Breakout Control\"><div class=\"ur-m\"><p class=\"tag\">Кожа, склонная к акне, и поры<\/p><h3>Breakout Control<\/h3><p class=\"bic\">Сыворотка · 30 мл<\/p><\/div><p class=\"fay\">Помогает уравновесить жирный вид кожи, склонной к акне, а порам — выглядеть чище.<\/p><a class=\"cta\" href=\"/ru/breakout-control-sivilce-akne-serumu\">СМОТРЕТЬ ПРОДУКТ<\/a><\/div><div class=\"ic-bl\"><section class=\"kt\"><p class=\"kt-u\">СОБСТВЕННЫЙ ТЕСТ ЭТОГО ПРОДУКТА<\/p><b>Не раздражает в тесте<\/b><p>В 48-часовом дерматологическом тесте с добровольцами с чувствительной кожей этот продукт вошел в класс «не раздражающий».<\/p><p>Продукт также прошел анализы на микробиологическое качество, защиту формулы от микробов, стабильность и тяжелые металлы.<\/p><p class=\"kay\"><em>Лабораторный отчет<\/em> SKINLAB, Краков · <a href=\"/ru/pages/test-sonuclarimiz\">Смотреть результаты тестов<\/a><\/p><\/section><section class=\"bl\"><h4>4 ключевых актива<\/h4><p class=\"ipucu\">Нажми на актив. Здесь откроются результат, измеренный в исследовании, источник и техническая заметка. Исследования проводились с самим активом, а не с этим продуктом.<\/p><div class=\"ak-iz\"><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-breakout-az\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/0b659cee906a.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для видимых высыпаний и покраснения<\/span><span class=\"ak-ad\" lang=\"en\">Azelaic Acid<\/span><span class=\"ak-o\">На этикетке: 5%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-breakout-az\" hidden><p class=\"ak-ac\">Помогает уменьшить видимость высыпаний и покраснения. Тон кожи выглядит ровнее.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>5%<\/b><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>5%<\/b><small>На людях<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>В группе, использовавшей 5% азелаиновую кислоту, балл тяжести высыпаний за 12 недель снизился на 32,46% по сравнению с исходным уровнем.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Научная статья<\/em> <a href=\"https://pubmed.ncbi.nlm.nih.gov/21612319/\" target=\"_blank\" rel=\"noopener\">Pazoki-Toroudi и соавт., Cutan Ocul Toxicol, 2011<\/a><\/p><p>150 человек случайным образом разделили на три группы. Исследование длилось 12 недель. Измеряли: число высыпаний, тяжесть высыпаний и удовлетворенность.<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>Многоцентровый двойной слепой дизайн с тремя группами и активным сравнением: 5% азелаиновая кислота, препарат сравнения, оба вместе. Индекс тяжести в группе 5% азелаиновой кислоты: −32,46% от исходного уровня.<\/p><\/section><\/div><\/article><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-breakout-sal\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/521be9e4e44c.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для пор<\/span><span class=\"ak-ad\" lang=\"en\">Salicylic Acid (BHA)<\/span><span class=\"ak-o\">На этикетке: 1%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-breakout-sal\" hidden><p class=\"ak-ac\">Жирорастворимая кислота (BHA), поэтому она может проникать внутрь поры. Помогает порам выглядеть менее заметными.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>1%<\/b><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>0,5%<\/b><small>На людях<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>В группе, использовавшей пэды с 0,5% салициловой кислоты, число высыпаний за 12 недель уменьшилось на 38,4%. В группе с пэдами, пропитанными водой со стабилизированной кислотностью (буферная вода), снижение составило 24,6%.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Научная статья<\/em> <a href=\"https://pubmed.ncbi.nlm.nih.gov/6458457/\" target=\"_blank\" rel=\"noopener\">Shalita, Cutis, 1981<\/a><\/p><p>49 человек разделили на две группы. Исследование длилось 12 недель. Измеряли: число высыпаний.<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>Активная группа n=25, пэд на спиртовой основе; контроль — буферная вода. Данные приводятся в обзоре Cochrane (Liu 2020).<\/p><\/section><\/div><\/article><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-breakout-zn\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/621c2bea3751.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для баланса жирности и матового вида<\/span><span class=\"ak-ad\" lang=\"en\">Zinc PCA<\/span><span class=\"ak-o\">На этикетке: 0,5%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-breakout-zn\" hidden><p class=\"ak-ac\">Поддерживает баланс жирности кожи. Помогает коже выглядеть более матовой.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>0,5%<\/b><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>0,3%<\/b><small>На людях<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>В тесте из патентного документа: в группе, использовавшей крем с 0,3% цинка PCA, кожное сало за 1 месяц уменьшилось на 43%. С кремом без цинка снижение составило 39%. 53% пользователей сочли контроль жирности эффективным. С кремом без цинка этот показатель составил 30%.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Патентный документ<\/em> CN120053345A, 2025<\/p><p>352 добровольца с жирной кожей разделили на 11 групп, примерно по 32 человека в каждой. Крем использовали 1 месяц.<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>Патентная заявка находится на рассмотрении. Несмываемый крем. В двух сравнениях с другими активами кожное сало в группе с цинком тоже снизилось сильнее: −49% против −38%, −48% против −40%.<\/p><\/section><\/div><\/article><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-breakout-bot\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/6a1ed71911d2.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для успокоения<\/span><span class=\"ak-ad\" lang=\"en\">7 Botanical Complex®<\/span><span class=\"ak-o\">На этикетке: 1,5%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-breakout-bot\" hidden><p class=\"ak-ac\">Успокаивающая смесь из семи растений. Есть во всех наших сыворотках, тониках и очищающих средствах.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>1,5%<\/b><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>1,5%<\/b><small>Тест на клетках<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>В лаборатории, в чашке с клетками: 7 Botanical Complex тестировали в концентрации 1,5%. В иммунных клетках человека, подвергнутых стрессу, три сигнала стресса снизились на 50,2–69,5% по сравнению с клетками без комплекса.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Тест производителя<\/em> Clariant, презентация MultiEx BSASM, 2023<\/p><p>Иммунные клетки человека подвергли стрессу и обработали комплексом. Измеряли: три сигнала стресса.<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>Моноциты человека THP-1, стресс LPS. При 1,5% опубликованные значения для IL-8, TNF-α и NF-κB: −50,2%, −52,7%, −69,5%.<\/p><\/section><\/div><\/article><\/div><\/section><section class=\"bl\"><h4>4 поддерживающих актива<\/h4><div class=\"ak-iz\"><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-breakout-nia\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/e146040b7101.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для барьера и баланса жирности<\/span><span class=\"ak-ad\" lang=\"en\">Niacinamide<\/span><span class=\"ak-o\">На коробке: 2%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-breakout-nia\" hidden><p class=\"ak-ac\">Витамин B3. Поддерживает защитный внешний слой кожи (барьер) и баланс жирности.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>2%<\/b><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>2%<\/b><small>На людях<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>В исследовании со 100 японскими добровольцами в группе, использовавшей 2% ниацинамид, выработка кожного сала заметно снизилась на 2-й и 4-й неделе.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Научная статья<\/em> <a href=\"https://pubmed.ncbi.nlm.nih.gov/16766489/\" target=\"_blank\" rel=\"noopener\">Draelos и соавт., J Cosmet Laser Ther, 2006<\/a><\/p><p>100 добровольцев разделили на две группы. Ни добровольцы, ни исследователи не знали, кто каким продуктом пользуется. Исследование длилось 4 недели. Сравнение проводили с неактивным продуктом (плацебо).<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>Измеряли скорость выделения кожного сала и поверхностный жир. У 30 добровольцев европеоидного типа при нанесении на половину лица поверхностный жир также уменьшился.<\/p><\/section><\/div><\/article><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-breakout-gly\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/5eb1bcbb08dc.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для увлажнения<\/span><span class=\"ak-ad\" lang=\"en\">Glycerin<\/span><span class=\"ak-o\">На коробке: 3%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-breakout-gly\" hidden><p class=\"ak-ac\">Притягивает влагу к поверхности кожи. Помогает уменьшить сухость кожи.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>3%<\/b><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>3%<\/b><small>На людях<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>В группе, использовавшей гель для рук с 3% глицерина, увлажненность кожи выросла по сравнению с исходной на 9,8% через 24 часа и на 11,9% на 8-й день.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Научная статья<\/em> Garcia и соавт., Asian J Beauty Cosmetol, 2023<\/p><p>Три группы, по 20 женщин в каждой, 20-63 лет. Гель для рук использовали 8 дней.<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>Спиртовой гель для рук, не менее 5 нанесений в день. Увлажненность измеряли Corneometer, потерю воды — Tewameter. Эта группа начинала с более низкой увлажненности; при последнем измерении группы были близки друг к другу.<\/p><\/section><\/div><\/article><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-breakout-bet\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/0af4e3778c4b.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для увлажнения<\/span><span class=\"ak-ad\" lang=\"en\">Betaine<\/span><span class=\"ak-o\">На коробке: 0,5%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-breakout-bet\" hidden><p class=\"ak-ac\">Помогает коже сохранять увлажненность.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>0,5%<\/b><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>0,1%<\/b><small>На людях<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>В тесте из патентного документа: лосьон с 0,1% бетаина использовали 5 дней. На предварительно раздраженной коже руки оценка шероховатости кожи изменилась в лучшую сторону как минимум у 80% участников. С лосьоном без бетаина этот показатель был ниже 30%.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Патентный документ<\/em> US6008246A, 1999<\/p><p>Кожу предплечья 10 мужчин сначала 3 дня раздражали. Лосьон наносили 2 раза в день, оценку проводили на 5-й день.<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>Модель повреждения 10% SLS, несмываемый лосьон. Шероховатость кожи оценивали методом реплик.<\/p><\/section><\/div><\/article><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-breakout-pan03\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/e8de229d733b.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для комфорта и увлажнения<\/span><span class=\"ak-ad\" lang=\"en\">Panthenol<\/span><span class=\"ak-o\">На коробке: 0,3%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-breakout-pan03\" hidden><p class=\"ak-ac\">В коже превращается в витамин B5. Помогает успокоить кожу и сохранить ее увлажненность.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>0,3%<\/b><small>сырье · 0,225% в чистом виде<\/small><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>0,03%<\/b><small>На людях<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>В тесте из патентного документа: в формуле с 0,03% пантенола число пор, измеренное на щеке, за 2 недели было примерно на 28% меньше, чем в такой же формуле без пантенола.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Патентный документ<\/em> JP2023-154112A, 2023<\/p><p>Каждую формулу, с пантенолом и без, 7 человек использовали 2 недели на коже щек.<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>Оценивали число и размер пор, шелушение и текстуру. В этом продукте сырье содержит 75% чистого вещества: 0,3% сырья, 0,225% чистого пантенола.<\/p><\/section><\/div><\/article><\/div><\/section><div class=\"alt-cta\"><a class=\"cta\" href=\"/ru/breakout-control-sivilce-akne-serumu\">СМОТРЕТЬ ПРОДУКТ<\/a><a class=\"ok\" href=\"#sec\">Посмотреть другую проблему<\/a><\/div><\/div><\/div><\/section><section class=\"panel\" id=\"p-calm\" role=\"tabpanel\" aria-labelledby=\"t-calm\" style=\"--k:#00788C\"><div class=\"ic pn\"><div class=\"ur\"><img class=\"ur-g\" loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/dfd0ab0ffd28.jpg\" alt=\"Calm Hug\"><div class=\"ur-m\"><p class=\"tag\">Покраснение и барьер<\/p><h3>Calm Hug<\/h3><p class=\"bic\">Сыворотка · 30 мл<\/p><\/div><p class=\"fay\">Помогает успокоить кожу, склонную к покраснению, и поддержать ее защитный внешний слой (барьер).<\/p><a class=\"cta\" href=\"/ru/calm-hug-hassas-cilt-serumu\">СМОТРЕТЬ ПРОДУКТ<\/a><\/div><div class=\"ic-bl\"><section class=\"kt\"><p class=\"kt-u\">СОБСТВЕННЫЙ ТЕСТ ЭТОГО ПРОДУКТА<\/p><b>Не раздражает в тесте<\/b><p>В 48-часовом дерматологическом тесте с добровольцами с чувствительной кожей этот продукт вошел в класс «не раздражающий».<\/p><p>Продукт также прошел анализы на микробиологическое качество, защиту формулы от микробов, стабильность и тяжелые металлы.<\/p><p class=\"kay\"><em>Лабораторный отчет<\/em> SKINLAB, Краков · <a href=\"/ru/pages/test-sonuclarimiz\">Смотреть результаты тестов<\/a><\/p><\/section><section class=\"bl\"><h4>4 ключевых актива<\/h4><p class=\"ipucu\">Нажми на актив. Здесь откроются результат, измеренный в исследовании, источник и техническая заметка. Исследования проводились с самим активом, а не с этим продуктом.<\/p><div class=\"ak-iz\"><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-calm-az\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/0b659cee906a.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для видимых высыпаний и покраснения<\/span><span class=\"ak-ad\" lang=\"en\">Azelaic Acid<\/span><span class=\"ak-o\">На этикетке: 5%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-calm-az\" hidden><p class=\"ak-ac\">Помогает уменьшить видимость высыпаний и покраснения. Тон кожи выглядит ровнее.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>5%<\/b><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>5%<\/b><small>На людях<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>В группе, использовавшей 5% азелаиновую кислоту, балл тяжести высыпаний за 12 недель снизился на 32,46% по сравнению с исходным уровнем. Покраснение в этом исследовании не измеряли.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Научная статья<\/em> <a href=\"https://pubmed.ncbi.nlm.nih.gov/21612319/\" target=\"_blank\" rel=\"noopener\">Pazoki-Toroudi и соавт., Cutan Ocul Toxicol, 2011<\/a><\/p><p>150 человек случайным образом разделили на три группы. Исследование длилось 12 недель. Измеряли: число высыпаний, тяжесть высыпаний и удовлетворенность.<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>Многоцентровый двойной слепой дизайн с тремя группами и активным сравнением: 5% азелаиновая кислота, препарат сравнения, оба вместе. Индекс тяжести в группе 5% азелаиновой кислоты: −32,46% от исходного уровня.<\/p><\/section><\/div><\/article><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-calm-ect\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/218248f95d18.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Против внешних воздействий<\/span><span class=\"ak-ad\" lang=\"en\">Ectoin<\/span><span class=\"ak-o\">На этикетке: 0,5%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-calm-ect\" hidden><p class=\"ak-ac\">Поддерживает кожу при внешних воздействиях.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>0,5%<\/b><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>0,5%<\/b><small>На людях<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>У женщин, использовавших крем с 0,5% эктоина, средняя глубина морщин в уголках глаз за 4 недели уменьшилась на 19%. Объем морщин уменьшился на 21%, шероховатость кожи — на 8%. С кремом без эктоина все три показателя выросли.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Тест производителя<\/em> bitop, брошюра Ectoin natural, 2018<\/p><p>10 женщин, 45-65 лет. Крем наносили в уголки глаз 2 раза в день 4 недели. Сравнение проводили с неактивным продуктом (плацебо).<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>Среднюю глубину морщин, объем и шероховатость измеряли PRIMOS. На стороне неактивного продукта: глубина +13%, объем +19%, шероховатость +27%.<\/p><\/section><\/div><\/article><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-calm-cer\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/085ff0d19407.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для барьера<\/span><span class=\"ak-ad\" lang=\"en\">Ceramide Complex<\/span><span class=\"ak-o\">На этикетке: 1%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-calm-cer\" hidden><p class=\"ak-ac\">Вид липидов, который есть и в структуре кожи. Поддерживает защитный внешний слой (барьер).<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>1%<\/b><small>комплекс<\/small><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>0,001%<\/b><small>церамид · на людях<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>В тесте из патентного документа: в группе, использовавшей маску для рук с 0,001% церамида, потеря воды кожей за 28 дней уменьшилась на 2,21%. С маской без церамида потеря воды выросла на 0,97%.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Патентный документ<\/em> CN115645308A, 2023<\/p><p>Маску для рук использовали раз в 3 дня в течение 28 дней. В каждой группе был 31 человек. Сравнение проводили с маской без церамида.<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>Комплекс с Ceramide NP: вода, PEG-7 Glyceryl Cocoate, Ceramide NP, Phenoxyethanol. 1% комплекса в этом продукте соответствует 0,005% церамида.<\/p><\/section><\/div><\/article><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-calm-bot\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/6a1ed71911d2.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для успокоения<\/span><span class=\"ak-ad\" lang=\"en\">7 Botanical Complex®<\/span><span class=\"ak-o\">На этикетке: 1%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-calm-bot\" hidden><p class=\"ak-ac\">Успокаивающая смесь из семи растений. Есть во всех наших сыворотках, тониках и очищающих средствах.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>1%<\/b><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>1%<\/b><small>Тест на клетках<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>В лаборатории, в чашке с клетками: 7 Botanical Complex тестировали в концентрации 1%. В иммунных клетках человека, подвергнутых стрессу, три сигнала стресса снизились примерно на 41–54% по сравнению с клетками без комплекса.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Тест производителя<\/em> Clariant, презентация MultiEx BSASM, 2023<\/p><p>Иммунные клетки человека подвергли стрессу и обработали комплексом. Измеряли: три сигнала стресса.<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>Моноциты человека THP-1, стресс LPS. При 1%: IL-8 примерно −43%, TNF-α примерно −41%, NF-κB примерно −54% (презентация производителя, график).<\/p><\/section><\/div><\/article><\/div><\/section><section class=\"bl\"><h4>4 поддерживающих актива<\/h4><div class=\"ak-iz\"><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-calm-bg\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/4fc900974add.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для успокоения и наполненного вида<\/span><span class=\"ak-ad\" lang=\"en\">Beta-Glucan<\/span><span class=\"ak-o\">На коробке: 0,3%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-calm-bg\" hidden><p class=\"ak-ac\">Помогает успокоить кожу. Помогает ей выглядеть более наполненной.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>0,3%<\/b><small>раствор · 0,0012% глюкана<\/small><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>0,0002%<\/b><small>глюкан · на людях, в составе смеси<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>0,0002% бета-глюкана 12 недель тестировали в креме вместе с двумя другими активами. В некоторых группах исследования был и прием внутрь. По сравнению с неактивным продуктом (плацебо) показатели кожи оказались лучше.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Научная статья<\/em> <a href=\"https://pubmed.ncbi.nlm.nih.gov/22456780/\" target=\"_blank\" rel=\"noopener\">Morganti и соавт., J Nutr Health Aging, 2012<\/a><\/p><p>70 здоровых женщин, 22-45 лет, случайным образом разделили на семь групп. Исследование проводили в нескольких центрах, оно длилось 12 недель.<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>Мелатонин, витамин E и бета-глюкан, каждый по 2 мкг/мл. Есть группы с местным и пероральным применением. Изменение параметров по сравнению с плацебо значимо (аннотация: p&lt;0,005).<\/p><\/section><\/div><\/article><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-calm-bak\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/64ee9f8d3409.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для обновленного вида<\/span><span class=\"ak-ad\" lang=\"en\">Bakuchiol<\/span><span class=\"ak-o\">На коробке: 0,2%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-calm-bak\" hidden><p class=\"ak-ac\">Растительный актив, это не ретинол. Помогает коже выглядеть обновленной.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>0,2%<\/b><small>сырье · 0,015% в чистом виде<\/small><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>0,01%<\/b><small>комплекс · тест на клетках<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>В лаборатории, в чашке с клетками: в клетках кожи, получивших 0,01% комплекса бакучиола, сообщалось о выработке коллагена выше на 75,11%, одном сигнале стресса ниже на 20,16% и ферментах, разрушающих коллаген, ниже на 51,87%. Сравнение проводили с бакучиолом и ретинолом.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Научная статья<\/em> Lu и соавт., Supramolecular Materials, 2025; цит. по Shi и соавт., Health Sci Rep, 2025<\/p><p>Использовали клетки кожи человека (фибробласты). Клеткам давали 0,01% комплекса бакучиола (супрамолекулярный бакучиол).<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>TNF-α −20,16%, MMP −51,87%, коллаген I +75,11%. Значения приведены в сравнении с бакучиолом и ретинолом.<\/p><\/section><\/div><\/article><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-calm-all\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/9d18fa4f8ecb.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для комфорта кожи<\/span><span class=\"ak-ad\" lang=\"en\">Allantoin<\/span><span class=\"ak-o\">На коробке: 0,1%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-calm-all\" hidden><p class=\"ak-ac\">Помогает успокоить и смягчить кожу.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>0,1%<\/b><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>0,01%<\/b><small>Тест на клетках<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>В лаборатории, в чашке с клетками: в клетках кожи человека, стимулированных молочной кислотой и получивших 0,01% аллантоина, снизилась активность одного гена стресса.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Научная статья<\/em> <a href=\"https://pubmed.ncbi.nlm.nih.gov/42352310/\" target=\"_blank\" rel=\"noopener\">Kim и соавт., Biomolecules, 2026<\/a><\/p><p>Использовали клетки кожи человека, стимулированные молочной кислотой. Аллантоин давали в концентрации 0,01% (100 мкг/мл).<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>Модель HaCaT и фибробластов человека. Экспрессию гена PTGS2 измеряли методом qRT-PCR.<\/p><\/section><\/div><\/article><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-calm-pt8\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/b3195f803070.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для кожи, ставшей чувствительной<\/span><span class=\"ak-ad\" lang=\"en\">Palmitoyl Tripeptide-8<\/span><span class=\"ak-o\">На коробке: 0,1%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-calm-pt8\" hidden><p class=\"ak-ac\">Короткая цепочка аминокислот (пептид). Помогает успокоить кожу, ставшую чувствительной.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>0,1%<\/b><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>0,0035%<\/b><small>раствор · тест на клетках<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>В лаборатории, в чашке с клетками: раствор пептида тестировали на клетках кожи, получивших УФ. Сигнал стресса снизился на 18% с раствором 0,0035% и на 32% с раствором 0,035%.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Тест производителя<\/em> Lucas Meyer Cosmetics, брошюра Neutrazen<\/p><p>Использовали клетки кожи человека, получившие UVB. Измеряли: сигнал IL-8.<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>Кератиноциты человека, модель UVB. Измеряли IL-8.<\/p><\/section><\/div><\/article><\/div><\/section><div class=\"alt-cta\"><a class=\"cta\" href=\"/ru/calm-hug-hassas-cilt-serumu\">СМОТРЕТЬ ПРОДУКТ<\/a><a class=\"ok\" href=\"#sec\">Посмотреть другую проблему<\/a><\/div><\/div><\/div><\/section><section class=\"panel\" id=\"p-juice\" role=\"tabpanel\" aria-labelledby=\"t-juice\" style=\"--k:#B25A10\"><div class=\"ic pn\"><div class=\"ur\"><img class=\"ur-g\" loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/3881dd2972ca.jpg\" alt=\"Juice Up\"><div class=\"ur-m\"><p class=\"tag\">Усталость и тусклость<\/p><h3>Juice Up<\/h3><p class=\"bic\">Сыворотка · 30 мл<\/p><\/div><p class=\"fay\">Помогает уставшей и тусклой на вид коже выглядеть сияющей и увлажненной.<\/p><a class=\"cta\" href=\"/ru/juice-up-c-vitamini-parlaklik-serumu\">СМОТРЕТЬ ПРОДУКТ<\/a><\/div><div class=\"ic-bl\"><section class=\"kt\"><p class=\"kt-u\">СОБСТВЕННЫЙ ТЕСТ ЭТОГО ПРОДУКТА<\/p><b>Не раздражает в тесте<\/b><p>В 48-часовом дерматологическом тесте с добровольцами с чувствительной кожей этот продукт вошел в класс «не раздражающий».<\/p><p>Продукт также прошел анализы на микробиологическое качество, защиту формулы от микробов, стабильность и тяжелые металлы.<\/p><p class=\"kay\"><em>Лабораторный отчет<\/em> SKINLAB, Краков · <a href=\"/ru/pages/test-sonuclarimiz\">Смотреть результаты тестов<\/a><\/p><\/section><section class=\"bl\"><h4>4 ключевых актива<\/h4><p class=\"ipucu\">Нажми на актив. Здесь откроются результат, измеренный в исследовании, источник и техническая заметка. Исследования проводились с самим активом, а не с этим продуктом.<\/p><div class=\"ak-iz\"><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-juice-lip\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/4ed597167970.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для сияющего вида<\/span><span class=\"ak-ad\" lang=\"en\">Liposomal Vitamin C Complex<\/span><span class=\"ak-o\">На этикетке: 3%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-juice-lip\" hidden><p class=\"ak-ac\">Производное витамина C. Переносится внутри крошечных пузырьков (липосом). Помогает коже выглядеть более сияющей.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>3%<\/b><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>2%<\/b><small>На людях<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>Сначала кожа получила УФ. Через 24 часа покраснение измерили прибором. В формуле с 2% липосомального витамина C покраснение было примерно на 28% ниже, чем в формуле без актива. Через 48 часов оно тоже было ниже. Этот результат не означает защиту от солнца.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Тест производителя<\/em> Infinitec, брошюра LPD Lightening<\/p><p>Покраснение отслеживали прибором (хромаметром) 48 часов. Сравнивали с продуктом без актива и с кожей, на которую ничего не наносили.<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>Индекс покраснения через 24 часа примерно 8,3 и 11,5, через 48 часов примерно 7,3 и 9,9 (2% и продукт без актива, график из брошюры).<\/p><\/section><\/div><\/article><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-juice-ect\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/218248f95d18.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Против внешних воздействий<\/span><span class=\"ak-ad\" lang=\"en\">Ectoin<\/span><span class=\"ak-o\">На этикетке: 0,5%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-juice-ect\" hidden><p class=\"ak-ac\">Поддерживает кожу при внешних воздействиях.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>0,5%<\/b><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>0,5%<\/b><small>На людях<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>У женщин, использовавших крем с 0,5% эктоина, средняя глубина морщин в уголках глаз за 4 недели уменьшилась на 19%. Объем морщин уменьшился на 21%, шероховатость кожи — на 8%. С кремом без эктоина все три показателя выросли.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Тест производителя<\/em> bitop, брошюра Ectoin natural, 2018<\/p><p>10 женщин, 45-65 лет. Крем наносили в уголки глаз 2 раза в день 4 недели. Сравнение проводили с неактивным продуктом (плацебо).<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>Среднюю глубину морщин, объем и шероховатость измеряли PRIMOS. На стороне неактивного продукта: глубина +13%, объем +19%, шероховатость +27%.<\/p><\/section><\/div><\/article><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-juice-caf\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/14a01dcaf725.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">При усталом виде кожи<\/span><span class=\"ak-ad\" lang=\"en\">Caffeine<\/span><span class=\"ak-o\">На этикетке: 0,5%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-juice-caf\" hidden><p class=\"ak-ac\">Помогает придать бодрый вид коже, которая выглядит уставшей.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>0,5%<\/b><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>0,5%<\/b><small>На людях<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>В геле с 0,5% кофеина показатель эластичности кожи лба за 4 недели вырос по сравнению с исходным с 61,35% до 69,54%. Чем выше значение, тем эластичнее кожа.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Научный доклад<\/em> Dewi и соавт., RCD 2018, с. 113-117<\/p><p>41 здоровый человек, 20-60 лет, случайным образом разделены на группы. Ни добровольцы, ни исследователи не знали, кто каким гелем пользуется. Исследование длилось 4 недели.<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>В геле с 0,5% кофеина эластичность лба выросла по сравнению с исходной (p=0,024).<\/p><\/section><\/div><\/article><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-juice-bot\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/6a1ed71911d2.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для успокоения<\/span><span class=\"ak-ad\" lang=\"en\">7 Botanical Complex®<\/span><span class=\"ak-o\">На этикетке: 1%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-juice-bot\" hidden><p class=\"ak-ac\">Успокаивающая смесь из семи растений. Есть во всех наших сыворотках, тониках и очищающих средствах.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>1%<\/b><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>1%<\/b><small>Тест на клетках<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>В лаборатории, в чашке с клетками: 7 Botanical Complex тестировали в концентрации 1%. В иммунных клетках человека, подвергнутых стрессу, три сигнала стресса снизились примерно на 41–54% по сравнению с клетками без комплекса.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Тест производителя<\/em> Clariant, презентация MultiEx BSASM, 2023<\/p><p>Иммунные клетки человека подвергли стрессу и обработали комплексом. Измеряли: три сигнала стресса.<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>Моноциты человека THP-1, стресс LPS. При 1%: IL-8 примерно −43%, TNF-α примерно −41%, NF-κB примерно −54% (презентация производителя, график).<\/p><\/section><\/div><\/article><\/div><\/section><section class=\"bl\"><h4>4 поддерживающих актива<\/h4><div class=\"ak-iz\"><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-juice-nia\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/e146040b7101.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для барьера и баланса жирности<\/span><span class=\"ak-ad\" lang=\"en\">Niacinamide<\/span><span class=\"ak-o\">На коробке: 2%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-juice-nia\" hidden><p class=\"ak-ac\">Витамин B3. Поддерживает защитный внешний слой кожи (барьер) и баланс жирности.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>2%<\/b><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>2%<\/b><small>На людях<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>В исследовании со 100 японскими добровольцами в группе, использовавшей 2% ниацинамид, выработка кожного сала заметно снизилась на 2-й и 4-й неделе.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Научная статья<\/em> <a href=\"https://pubmed.ncbi.nlm.nih.gov/16766489/\" target=\"_blank\" rel=\"noopener\">Draelos и соавт., J Cosmet Laser Ther, 2006<\/a><\/p><p>100 добровольцев разделили на две группы. Ни добровольцы, ни исследователи не знали, кто каким продуктом пользуется. Исследование длилось 4 недели. Сравнение проводили с неактивным продуктом (плацебо).<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>Измеряли скорость выделения кожного сала и поверхностный жир. У 30 добровольцев европеоидного типа при нанесении на половину лица поверхностный жир также уменьшился.<\/p><\/section><\/div><\/article><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-juice-pan3\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/e8de229d733b.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для комфорта и увлажнения<\/span><span class=\"ak-ad\" lang=\"en\">Panthenol<\/span><span class=\"ak-o\">На коробке: 0,5%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-juice-pan3\" hidden><p class=\"ak-ac\">В коже превращается в витамин B5. Помогает успокоить кожу и сохранить ее увлажненность.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>0,5%<\/b><small>сырье · 0,375% в чистом виде<\/small><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>0,3%<\/b><small>На людях<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>В тесте из патентного документа: в формуле с 0,3% пантенола число пор, измеренное на щеке, за 2 недели было примерно на 21% меньше, чем в такой же формуле без пантенола. Размер пор также оценивали визуально. По сравнению с формулой без пантенола балл был примерно на 33% ниже. Более низкий балл означает более мелкие поры.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Патентный документ<\/em> JP2023-154112A, 2023<\/p><p>Каждую формулу, с пантенолом и без, 7 человек использовали 2 недели на коже щек.<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>Оценивали число и размер пор, шелушение и текстуру. Сырье в этом продукте содержит 75% чистого вещества.<\/p><\/section><\/div><\/article><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-juice-ha\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/7656d34adb24.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для увлажнения и наполненного вида<\/span><span class=\"ak-ad\" lang=\"en\">Hyaluronic Acid<\/span><span class=\"ak-o\">На коробке: 0,2%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-juice-ha\" hidden><p class=\"ak-ac\">Удерживает влагу на поверхности кожи. Помогает ей выглядеть более наполненной.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>0,2%<\/b><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>0,1%<\/b><small>На людях<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>В исследовании с 21 женщиной 0,1% низкомолекулярной (2 кДа) гиалуроновой кислоты наносили на одну половину лица. Через 8 недель самые глубокие линии в уголках глаз и вокруг носа и рта на этой половине были менее глубокими, чем на другой.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Научная статья<\/em> <a href=\"https://pubmed.ncbi.nlm.nih.gov/35587723/\" target=\"_blank\" rel=\"noopener\">Abe и соавт., J Cosmet Dermatol, 2023<\/a><\/p><p>Участвовала 21 женщина. На какую половину лица наносить лосьон, выбирали случайным образом. Лосьон наносили 2 раза в день 8 недель. На другую половину наносили такой же лосьон без гиалуроновой кислоты.<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>Split-face, n=21, p&lt;0,05. Измеряли глубину морщин, эластичность и плотность коллагена.<\/p><\/section><\/div><\/article><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-juice-bg\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/4fc900974add.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для успокоения и наполненного вида<\/span><span class=\"ak-ad\" lang=\"en\">Beta-Glucan<\/span><span class=\"ak-o\">На коробке: 0,2%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-juice-bg\" hidden><p class=\"ak-ac\">Помогает успокоить кожу. Помогает ей выглядеть более наполненной.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>0,2%<\/b><small>раствор · 0,0008% глюкана<\/small><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>0,0002%<\/b><small>глюкан · на людях, в составе смеси<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>0,0002% бета-глюкана 12 недель тестировали в креме вместе с двумя другими активами. В некоторых группах исследования был и прием внутрь. По сравнению с неактивным продуктом (плацебо) показатели кожи оказались лучше.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Научная статья<\/em> <a href=\"https://pubmed.ncbi.nlm.nih.gov/22456780/\" target=\"_blank\" rel=\"noopener\">Morganti и соавт., J Nutr Health Aging, 2012<\/a><\/p><p>70 здоровых женщин, 22-45 лет, случайным образом разделили на семь групп. Исследование проводили в нескольких центрах, оно длилось 12 недель.<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>Мелатонин, витамин E и бета-глюкан, каждый по 2 мкг/мл. Есть группы с местным и пероральным применением. Изменение параметров по сравнению с плацебо значимо (аннотация: p&lt;0,005).<\/p><\/section><\/div><\/article><\/div><\/section><div class=\"alt-cta\"><a class=\"cta\" href=\"/ru/juice-up-c-vitamini-parlaklik-serumu\">СМОТРЕТЬ ПРОДУКТ<\/a><a class=\"ok\" href=\"#sec\">Посмотреть другую проблему<\/a><\/div><\/div><\/div><\/section><section class=\"panel\" id=\"p-spot\" role=\"tabpanel\" aria-labelledby=\"t-spot\" style=\"--k:#23618D\"><div class=\"ic pn\"><div class=\"ur\"><img class=\"ur-g\" loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/29784e8950a2.jpg\" alt=\"Spot Less\"><div class=\"ur-m\"><p class=\"tag\">Пятна и тон<\/p><h3>Spot Less<\/h3><p class=\"bic\">Сыворотка · 30 мл<\/p><\/div><p class=\"fay\">Помогает тону кожи выглядеть более ровным и сияющим.<\/p><a class=\"cta\" href=\"/ru/spot-less-leke-serumu-2\">СМОТРЕТЬ ПРОДУКТ<\/a><\/div><div class=\"ic-bl\"><section class=\"kt\"><p class=\"kt-u\">СОБСТВЕННЫЙ ТЕСТ ЭТОГО ПРОДУКТА<\/p><b>Не раздражает в тесте<\/b><p>В 48-часовом дерматологическом тесте с добровольцами с чувствительной кожей этот продукт вошел в класс «не раздражающий».<\/p><p>Продукт также прошел анализы на микробиологическое качество, защиту формулы от микробов, стабильность и тяжелые металлы.<\/p><p class=\"kay\"><em>Лабораторный отчет<\/em> SKINLAB, Краков · <a href=\"/ru/pages/test-sonuclarimiz\">Смотреть результаты тестов<\/a><\/p><\/section><section class=\"bl\"><h4>4 ключевых актива<\/h4><p class=\"ipucu\">Нажми на актив. Здесь откроются результат, измеренный в исследовании, источник и техническая заметка. Исследования проводились с самим активом, а не с этим продуктом.<\/p><div class=\"ak-iz\"><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-spot-txa\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/d78935c3a3c8.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для видимых пятен и тона<\/span><span class=\"ak-ad\" lang=\"en\">Tranexamic Acid<\/span><span class=\"ak-o\">На этикетке: 3%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-spot-txa\" hidden><p class=\"ak-ac\">Помогает пятнам выглядеть менее заметными. Помогает тону кожи выглядеть ровнее.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>3%<\/b><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>3%<\/b><small>На людях<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>У женщин с умеренными и выраженными пятнами на лице на одну половину лица наносили 3% транексамовой кислоты. Балл пятен (MASI) за 12 недель снизился с 31,68 до 10,76. Чем ниже балл, тем меньше измеренных пятен.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Научная статья<\/em> <a href=\"https://pubmed.ncbi.nlm.nih.gov/25422661/\" target=\"_blank\" rel=\"noopener\">Ebrahimi и Naeini, J Res Med Sci, 2014<\/a><\/p><p>Начали 50 женщин, завершили 39. Транексамовую кислоту наносили на одну половину лица 2 раза в день 12 недель. Ни добровольцы, ни исследователи не знали, на какую половину что наносили.<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>MASI на стороне 3% TXA: 31,68→10,76; на другой стороне группа активного сравнения: 29,52→10,48. Разница между группами незначима. Побочные эффекты чаще на другой стороне.<\/p><\/section><\/div><\/article><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-spot-lip\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/4ed597167970.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для сияющего вида<\/span><span class=\"ak-ad\" lang=\"en\">Liposomal Vitamin C Complex<\/span><span class=\"ak-o\">На этикетке: 3%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-spot-lip\" hidden><p class=\"ak-ac\">Производное витамина C. Переносится внутри крошечных пузырьков (липосом). Помогает коже выглядеть более сияющей.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>3%<\/b><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>2%<\/b><small>На людях<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>Сначала кожа получила УФ. Через 24 часа покраснение измерили прибором. В формуле с 2% липосомального витамина C покраснение было примерно на 28% ниже, чем в формуле без актива. Через 48 часов оно тоже было ниже. Этот результат не означает защиту от солнца.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Тест производителя<\/em> Infinitec, брошюра LPD Lightening<\/p><p>Покраснение отслеживали прибором (хромаметром) 48 часов. Сравнивали с продуктом без актива и с кожей, на которую ничего не наносили.<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>Индекс покраснения через 24 часа примерно 8,3 и 11,5, через 48 часов примерно 7,3 и 9,9 (2% и продукт без актива, график из брошюры).<\/p><\/section><\/div><\/article><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-spot-arb\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/e6a478fcaed1.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для сияющего вида и тона<\/span><span class=\"ak-ad\" lang=\"en\">Alpha-Arbutin<\/span><span class=\"ak-o\">На этикетке: 1,5%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-spot-arb\" hidden><p class=\"ak-ac\">Мягкий актив. Помогает коже выглядеть сияющей. Помогает сделать разницу в цвете менее заметной.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>1,5%<\/b><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>1%<\/b><small>На людях<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>В тесте с кремоподобным продуктом (эмульсией) с 1% альфа-арбутина светлота кожи на участке предплечья, куда его наносили, за 1 месяц выросла по сравнению с контролем.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Тест производителя<\/em> DSM, брошюра Alpha-Arbutin, 2020<\/p><p>Четыре разные эмульсии наносили на предплечье 80 женщин 2 раза в день 1 месяц.<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>Значение L* хромаметра выросло по сравнению с контролем примерно на 0,88% (график из брошюры).<\/p><\/section><\/div><\/article><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-spot-bot\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/6a1ed71911d2.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для успокоения<\/span><span class=\"ak-ad\" lang=\"en\">7 Botanical Complex®<\/span><span class=\"ak-o\">На этикетке: 1%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-spot-bot\" hidden><p class=\"ak-ac\">Успокаивающая смесь из семи растений. Есть во всех наших сыворотках, тониках и очищающих средствах.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>1%<\/b><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>1%<\/b><small>Тест на клетках<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>В лаборатории, в чашке с клетками: 7 Botanical Complex тестировали в концентрации 1%. В иммунных клетках человека, подвергнутых стрессу, три сигнала стресса снизились примерно на 41–54% по сравнению с клетками без комплекса.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Тест производителя<\/em> Clariant, презентация MultiEx BSASM, 2023<\/p><p>Иммунные клетки человека подвергли стрессу и обработали комплексом. Измеряли: три сигнала стресса.<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>Моноциты человека THP-1, стресс LPS. При 1%: IL-8 примерно −43%, TNF-α примерно −41%, NF-κB примерно −54% (презентация производителя, график).<\/p><\/section><\/div><\/article><\/div><\/section><section class=\"bl\"><h4>4 поддерживающих актива<\/h4><div class=\"ak-iz\"><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-spot-nia1\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/e146040b7101.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для барьера и баланса жирности<\/span><span class=\"ak-ad\" lang=\"en\">Niacinamide<\/span><span class=\"ak-o\">На коробке: 1%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-spot-nia1\" hidden><p class=\"ak-ac\">Витамин B3. Поддерживает защитный внешний слой кожи (барьер) и баланс жирности.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>1%<\/b><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>1%<\/b><small>На людях<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>В группе, использовавшей гель с 1% ниацинамида, число шероховатых участков на коже, поврежденной солнцем, за 3 месяца уменьшилось на 21,8%. С гелем без этого вещества снижение составило 10%. Исследование проводили у людей с повреждением кожи от солнца.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Научная статья<\/em> <a href=\"https://pubmed.ncbi.nlm.nih.gov/20199551/\" target=\"_blank\" rel=\"noopener\">Moloney и соавт., Br J Dermatol, 2010<\/a><\/p><p>30 человек случайным образом разделили на группы. Ни добровольцы, ни исследователи не знали, кто каким гелем пользуется. Гель наносили 2 раза в день.<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>Число очагов на коже, поврежденной солнцем, дизайн с контролем неактивным продуктом. 1% никотинамида, исследование на 6 месяцев; результат — измерение на 3-м месяце. Название диагноза указано в исходной статье.<\/p><\/section><\/div><\/article><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-spot-ha5\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/7656d34adb24.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для увлажнения и наполненного вида<\/span><span class=\"ak-ad\" lang=\"en\">5D Hyaluronic Acid<\/span><span class=\"ak-o\">На коробке: 0,8%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-spot-ha5\" hidden><p class=\"ak-ac\">Удерживает влагу на поверхности кожи. Помогает ей выглядеть более наполненной.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>0,8%<\/b><small>сырье<\/small><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>0,01%<\/b><small>Тест на клетках<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>В лаборатории, в чашке с клетками: в клетке кожи, получившей 0,01% низкомолекулярной (50 кДа) гиалуроновой кислоты, активность гена, вырабатывающего гиалуроновую кислоту, выросла примерно в 2,6 раза.<\/p><p>В тесте из патентного документа: из 20 женщин, использовавших крем примерно с 0,02% очень короткоцепочечной (2-6 сахаров) гиалуроновой кислоты, 18 при оценке пятен поставили одну из двух самых высоких оценок.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Тест производителя<\/em> Evonik, брошюра HyaCare 50<\/p><p>Клеткам кожи человека 24 часа давали гиалуроновую кислоту. Опыт повторили 3 раза.<\/p><\/div><div><p class=\"z-a\"><em>Патентный документ<\/em> JP2015-040173A, 2015<\/p><p>В каждой группе 20 человек использовали крем 1 месяц. Сравнение проводили с кремом с более высокомолекулярной гиалуроновой кислотой.<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>Показатель HAS-2: при 0,01% примерно 2,6, при 0,001% примерно 2,0 (p&lt;0,05, график). В 0,8% сырья в этом продукте содержится 0,0256% HA и 0,0288% гидролизованного гликозаминогликана, всего 0,0544%.<\/p><\/section><\/div><\/article><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-spot-pan3\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/e8de229d733b.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для комфорта и увлажнения<\/span><span class=\"ak-ad\" lang=\"en\">Panthenol<\/span><span class=\"ak-o\">На коробке: 0,5%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-spot-pan3\" hidden><p class=\"ak-ac\">В коже превращается в витамин B5. Помогает успокоить кожу и сохранить ее увлажненность.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>0,5%<\/b><small>сырье · 0,375% в чистом виде<\/small><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>0,3%<\/b><small>На людях<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>В тесте из патентного документа: в формуле с 0,3% пантенола число пор, измеренное на щеке, за 2 недели было примерно на 21% меньше, чем в такой же формуле без пантенола. Размер пор также оценивали визуально. По сравнению с формулой без пантенола балл был примерно на 33% ниже. Более низкий балл означает более мелкие поры.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Патентный документ<\/em> JP2023-154112A, 2023<\/p><p>Каждую формулу, с пантенолом и без, 7 человек использовали 2 недели на коже щек.<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>Оценивали число и размер пор, шелушение и текстуру. Сырье в этом продукте содержит 75% чистого вещества.<\/p><\/section><\/div><\/article><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-spot-cer\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/085ff0d19407.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для барьера<\/span><span class=\"ak-ad\" lang=\"en\">Ceramide Complex<\/span><span class=\"ak-o\">На коробке: 0,1%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-spot-cer\" hidden><p class=\"ak-ac\">Вид липидов, который есть и в структуре кожи. Поддерживает защитный внешний слой (барьер).<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>0,1%<\/b><small>комплекс<\/small><\/div><\/div><section class=\"z\"><h6>РОЛЬ В ЭТОМ ПРОДУКТЕ<\/h6><p>Церамид NP — липид, который в естественном виде есть в защитном внешнем слое кожи. В Spot Less используется для поддержки барьера.<\/p><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>Комплекс с Ceramide NP: вода, PEG-7 Glyceryl Cocoate, Ceramide NP, Phenoxyethanol.<\/p><\/section><\/div><\/article><\/div><\/section><div class=\"alt-cta\"><a class=\"cta\" href=\"/ru/spot-less-leke-serumu-2\">СМОТРЕТЬ ПРОДУКТ<\/a><a class=\"ok\" href=\"#sec\">Посмотреть другую проблему<\/a><\/div><\/div><\/div><\/section><section class=\"panel\" id=\"p-time\" role=\"tabpanel\" aria-labelledby=\"t-time\" style=\"--k:#6450B0\"><div class=\"ic pn\"><div class=\"ur\"><img class=\"ur-g\" loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/63d753b95aec.jpg\" alt=\"Time Warp\"><div class=\"ur-m\"><p class=\"tag\">Старение и морщины<\/p><h3>Time Warp<\/h3><p class=\"bic\">Сыворотка · 30 мл<\/p><\/div><p class=\"fay\">Помогает тонким морщинам выглядеть менее заметными. Помогает коже выглядеть более наполненной.<\/p><a class=\"cta\" href=\"/ru/time-warp-peptide-serum-2\">СМОТРЕТЬ ПРОДУКТ<\/a><\/div><div class=\"ic-bl\"><section class=\"kt\"><p class=\"kt-u\">СОБСТВЕННЫЙ ТЕСТ ЭТОГО ПРОДУКТА<\/p><b>Не раздражает в тесте<\/b><p>В 48-часовом дерматологическом тесте с добровольцами с чувствительной кожей этот продукт вошел в класс «не раздражающий».<\/p><p>Продукт также прошел анализы на микробиологическое качество, защиту формулы от микробов, стабильность и тяжелые металлы.<\/p><p class=\"kay\"><em>Лабораторный отчет<\/em> SKINLAB, Краков · <a href=\"/ru/pages/test-sonuclarimiz\">Смотреть результаты тестов<\/a><\/p><\/section><section class=\"bl\"><h4>4 ключевых актива<\/h4><p class=\"ipucu\">Нажми на актив. Здесь откроются результат, измеренный в исследовании, источник и техническая заметка. Исследования проводились с самим активом, а не с этим продуктом.<\/p><div class=\"ak-iz\"><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-time-arg\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/4e7e23411509.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для мимических морщин<\/span><span class=\"ak-ad\" lang=\"en\">Argireline<\/span><span class=\"ak-o\">На этикетке: 2%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-time-arg\" hidden><p class=\"ak-ac\">Раствор пептида. Помогает морщинкам, которые появляются при улыбке и когда хмуришься, выглядеть мягче.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>2%<\/b><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>2%<\/b><small>На людях<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>На половине лица, где наносили 2% раствор Argireline Amplified, площадь морщин в уголках глаз за 28 дней уменьшилась на 12,4%. С кремом без этого вещества снижение составило примерно 7,5%.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Тест производителя<\/em> Lubrizol, презентация Argireline Amplified, 2020<\/p><p>41 женщина, 35-59 лет. Крем наносили на одну половину лица 2 раза в день 28 дней.<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>Площадь морщин в уголках глаз измеряли PRIMOS. На 28-й день p&lt;0,05 по сравнению с неактивным продуктом. Тест проводили с другим коммерческим сырьем, не с тем, что в продукте.<\/p><\/section><\/div><\/article><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-time-mat\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/90824fa8c3f0.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для упругого вида<\/span><span class=\"ak-ad\" lang=\"en\">Matrixyl 3000<\/span><span class=\"ak-o\">На этикетке: 3%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-time-mat\" hidden><p class=\"ak-ac\">Смесь из двух пептидов. Помогает коже выглядеть более упругой.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>3%<\/b><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>3%<\/b><small>На людях<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>В тесте с кремом с 3% Matrixyl 3000 площадь глубоких морщин у 23 женщин за 2 месяца уменьшилась на 39,4% по сравнению с исходной. Глубина морщин уменьшилась на 19,9%.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Тест производителя<\/em> Sederma, документ Matrixyl 3000, 2015<\/p><p>23 женщины, 42-67 лет. Крем наносили на одну половину лица 2 раза в день 2 месяца. На другую половину наносили неактивный продукт (плацебо).<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>Профилометрия: площадь глубоких морщин −39,4%, глубина −19,9%, объем −23,3%. На стороне неактивного продукта площадь +4,3% и глубина −3,2% (оба изменения незначимы), объем −8,7%. Тест проводили с другим коммерческим сырьем, не с тем, что в продукте.<\/p><\/section><\/div><\/article><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-time-bak\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/64ee9f8d3409.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для обновленного вида<\/span><span class=\"ak-ad\" lang=\"en\">Bakuchiol<\/span><span class=\"ak-o\">На этикетке: 1%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-time-bak\" hidden><p class=\"ak-ac\">Растительный актив, это не ретинол. Помогает коже выглядеть обновленной.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>1%<\/b><small>сырье · 0,075% в чистом виде<\/small><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>0,05%<\/b><small>фракция · на людях<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>В тесте из патентного документа: лосьон с экстрактом бакучиола 1 месяц наносили на кожу руки, подвергавшуюся солнцу. При оценке пятен у 13 из 15 человек рука с экстрактом получила самый высокий балл, у 2 — второй по величине. На руке без экстракта самого высокого балла не получил никто.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Патентный документ<\/em> JP H11-071231A, 1999<\/p><p>15 здоровых человек, 20-45 лет. На левую руку наносили лосьон с экстрактом, на правую — без экстракта, 2 раза в день 1 месяц.<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>Вещество — фракция с содержанием бакучиола 79-91%; 0,05% фракции соответствует примерно 0,04-0,046% чистого бакучиола. В этом продукте 0,075% чистого бакучиола. На руке без экстракта 1 человек получил второй балл, 8 человек — третий, 6 человек — самый низкий.<\/p><\/section><\/div><\/article><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-time-bot\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/6a1ed71911d2.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для успокоения<\/span><span class=\"ak-ad\" lang=\"en\">7 Botanical Complex®<\/span><span class=\"ak-o\">На этикетке: 1%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-time-bot\" hidden><p class=\"ak-ac\">Успокаивающая смесь из семи растений. Есть во всех наших сыворотках, тониках и очищающих средствах.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>1%<\/b><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>1%<\/b><small>Тест на клетках<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>В лаборатории, в чашке с клетками: 7 Botanical Complex тестировали в концентрации 1%. В иммунных клетках человека, подвергнутых стрессу, три сигнала стресса снизились примерно на 41–54% по сравнению с клетками без комплекса.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Тест производителя<\/em> Clariant, презентация MultiEx BSASM, 2023<\/p><p>Иммунные клетки человека подвергли стрессу и обработали комплексом. Измеряли: три сигнала стресса.<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>Моноциты человека THP-1, стресс LPS. При 1%: IL-8 примерно −43%, TNF-α примерно −41%, NF-κB примерно −54% (презентация производителя, график).<\/p><\/section><\/div><\/article><\/div><\/section><section class=\"bl\"><h4>5 поддерживающих активов<\/h4><div class=\"ak-iz\"><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-time-nia\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/e146040b7101.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для барьера и баланса жирности<\/span><span class=\"ak-ad\" lang=\"en\">Niacinamide<\/span><span class=\"ak-o\">На коробке: 2%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-time-nia\" hidden><p class=\"ak-ac\">Витамин B3. Поддерживает защитный внешний слой кожи (барьер) и баланс жирности.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>2%<\/b><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>2%<\/b><small>На людях<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>В исследовании со 100 японскими добровольцами в группе, использовавшей 2% ниацинамид, выработка кожного сала заметно снизилась на 2-й и 4-й неделе.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Научная статья<\/em> <a href=\"https://pubmed.ncbi.nlm.nih.gov/16766489/\" target=\"_blank\" rel=\"noopener\">Draelos и соавт., J Cosmet Laser Ther, 2006<\/a><\/p><p>100 добровольцев разделили на две группы. Ни добровольцы, ни исследователи не знали, кто каким продуктом пользуется. Исследование длилось 4 недели. Сравнение проводили с неактивным продуктом (плацебо).<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>Измеряли скорость выделения кожного сала и поверхностный жир. У 30 добровольцев европеоидного типа при нанесении на половину лица поверхностный жир также уменьшился.<\/p><\/section><\/div><\/article><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-time-tre\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/d2278a00788a.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для увлажнения и наполненного вида<\/span><span class=\"ak-ad\" lang=\"en\">Tremella Extract Complex<\/span><span class=\"ak-o\">На коробке: 1%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-time-tre\" hidden><p class=\"ak-ac\">Получают из гриба тремелла. Помогает коже выглядеть увлажненной и наполненной.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>1%<\/b><small>раствор · 0,021% экстракта<\/small><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>0,02%<\/b><small>экстракт · тест на клетках<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>В лаборатории, в чашке с клетками: в клетках кожи человека, получивших 0,02% экстракта тремеллы, синтез ДНК вырос примерно до 130% от уровня клеток без экстракта.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Научная статья<\/em> <a href=\"https://pubmed.ncbi.nlm.nih.gov/42451721/\" target=\"_blank\" rel=\"noopener\">Wolosik и соавт., Molecules, 2026<\/a><\/p><p>Клеткам кожи человека (фибробластам) давали 200 мкг/мл (0,02%) коммерческого экстракта. Сравнение проводили с клетками без экстракта.<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>Измеряли жизнеспособность, синтез ДНК и коллагена, тест на закрытие царапины.<\/p><\/section><\/div><\/article><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-time-pul\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/1a8ff3fdcc7b.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для мгновенного ощущения подтянутости<\/span><span class=\"ak-ad\" lang=\"en\">Pullulan<\/span><span class=\"ak-o\">На коробке: 0,3%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-time-pul\" hidden><p class=\"ak-ac\">Образует на коже тонкую пленку. При нанесении дает ощущение подтянутости.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>0,3%<\/b><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>0,05%<\/b><small>На людях<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>В тесте из патентного документа: 20 женщин из оценочной панели пробовали одну и ту же жидкость с разными концентрациями. Для жидкости с 0,05% пуллулана ощущение подтянутости оценили как хорошее не менее 18 человек. Для жидкости без пуллулана таких было не больше 8.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Патентный документ<\/em> JP2025-113526A, 2025<\/p><p>20 женщин из оценочной панели оценивали жидкость сразу после использования. Измеряли: ощущение подтянутости.<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>Сенсорная оценка (ощущение стягивания). Патент считает достаточным диапазон 0,01-2%, а особенно хорошим — 0,05-1%.<\/p><\/section><\/div><\/article><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-time-ha\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/7656d34adb24.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для увлажнения и наполненного вида<\/span><span class=\"ak-ad\" lang=\"en\">Hyaluronic Acid<\/span><span class=\"ak-o\">На коробке: 0,25%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-time-ha\" hidden><p class=\"ak-ac\">Удерживает влагу на поверхности кожи. Помогает ей выглядеть более наполненной.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>0,25%<\/b><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>0,1%<\/b><small>На людях<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>В исследовании с 21 женщиной 0,1% низкомолекулярной (2 кДа) гиалуроновой кислоты наносили на одну половину лица. Через 8 недель самые глубокие линии в уголках глаз и вокруг носа и рта на этой половине были менее глубокими, чем на другой.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Научная статья<\/em> <a href=\"https://pubmed.ncbi.nlm.nih.gov/35587723/\" target=\"_blank\" rel=\"noopener\">Abe и соавт., J Cosmet Dermatol, 2023<\/a><\/p><p>Участвовала 21 женщина. На какую половину лица наносить лосьон, выбирали случайным образом. Лосьон наносили 2 раза в день 8 недель. На другую половину наносили такой же лосьон без гиалуроновой кислоты.<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>Split-face, n=21, p&lt;0,05. Измеряли глубину морщин, эластичность и плотность коллагена.<\/p><\/section><\/div><\/article><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-time-cer\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/085ff0d19407.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для барьера<\/span><span class=\"ak-ad\" lang=\"en\">Ceramide Complex<\/span><span class=\"ak-o\">На коробке: 0,2%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-time-cer\" hidden><p class=\"ak-ac\">Вид липидов, который есть и в структуре кожи. Поддерживает защитный внешний слой (барьер).<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>0,2%<\/b><small>комплекс<\/small><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>0,001%<\/b><small>церамид · на людях<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>В тесте из патентного документа: в группе, использовавшей маску для рук с 0,001% церамида, потеря воды кожей за 28 дней уменьшилась на 2,21%. С маской без церамида потеря воды выросла на 0,97%.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Патентный документ<\/em> CN115645308A, 2023<\/p><p>Маску для рук использовали раз в 3 дня в течение 28 дней. В каждой группе был 31 человек. Сравнение проводили с маской без церамида.<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>Комплекс с Ceramide NP: вода, PEG-7 Glyceryl Cocoate, Ceramide NP, Phenoxyethanol. 0,2% комплекса в этом продукте соответствует 0,001% церамида.<\/p><\/section><\/div><\/article><\/div><\/section><div class=\"alt-cta\"><a class=\"cta\" href=\"/ru/time-warp-peptide-serum-2\">СМОТРЕТЬ ПРОДУКТ<\/a><a class=\"ok\" href=\"#sec\">Посмотреть другую проблему<\/a><\/div><\/div><\/div><\/section><section class=\"panel\" id=\"p-reborn\" role=\"tabpanel\" aria-labelledby=\"t-reborn\" style=\"--k:#33302D\"><div class=\"ic pn\"><div class=\"ur\"><img class=\"ur-g\" loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/ea6f3d57ecdb.jpg\" alt=\"Reborn+ Cleanser\"><div class=\"ur-m\"><p class=\"tag\">Поры и текстура<\/p><h3>Reborn+ Cleanser<\/h3><p class=\"bic\">Очищающее средство · 200 мл<\/p><\/div><p class=\"fay\">Мягко очищает кожу. Помогает порам и текстуре кожи выглядеть более ровными.<\/p><a class=\"cta\" href=\"/ru/reborn-plus-temizleme-jeli\">СМОТРЕТЬ ПРОДУКТ<\/a><\/div><div class=\"ic-bl\"><section class=\"kt\"><p class=\"kt-u\">СОБСТВЕННЫЙ ТЕСТ ЭТОГО ПРОДУКТА<\/p><b>Не раздражает в тесте<\/b><p>В 48-часовом дерматологическом тесте с добровольцами с чувствительной кожей этот продукт вошел в класс «не раздражающий».<\/p><p>Продукт также прошел анализы на микробиологическое качество, защиту формулы от микробов, стабильность и тяжелые металлы.<\/p><p class=\"kay\"><em>Лабораторный отчет<\/em> SKINLAB, Краков · <a href=\"/ru/pages/test-sonuclarimiz\">Смотреть результаты тестов<\/a><\/p><\/section><section class=\"bl\"><h4>4 ключевых актива<\/h4><p class=\"ipucu\">Нажми на актив. Здесь откроются результат, измеренный в исследовании, источник и техническая заметка. Исследования проводились с самим активом, а не с этим продуктом.<\/p><div class=\"ak-iz\"><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-reborn-pha\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/69afeee4d496.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для мягкого обновления поверхности<\/span><span class=\"ak-ad\" lang=\"en\">Gluconolactone (PHA)<\/span><span class=\"ak-o\">На этикетке: 4%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-reborn-pha\" hidden><p class=\"ak-ac\">Кислота (PHA), которая мягко обновляет поверхность кожи. Ее молекула крупная, поэтому она работает в основном на поверхности.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>4%<\/b><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>3%<\/b><small>На людях<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>На коже, где использовали крем с 3% глюконолактона (PHA), увлажненность была на 25% выше, чем на коже, на которую ничего не наносили. По сравнению с кремом без увлажняющих компонентов разница составила 10%.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Тест производителя<\/em> Jungbunzlauer, брошюра Personal Care, 2023<\/p><p>Крем сравнивали с участком, на который ничего не наносили, и с кремом без увлажняющих компонентов. Измеряли: увлажненность кожи.<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>Увлажненность кожи измеряли Corneometer. Исследование проводили с несмываемым продуктом. Reborn+ — смываемое очищающее средство.<\/p><\/section><\/div><\/article><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-reborn-zn\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/621c2bea3751.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для баланса жирности и матового вида<\/span><span class=\"ak-ad\" lang=\"en\">Zinc PCA<\/span><span class=\"ak-o\">На этикетке: 0,5%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-reborn-zn\" hidden><p class=\"ak-ac\">Поддерживает баланс жирности кожи. Помогает коже выглядеть более матовой.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>0,5%<\/b><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>0,5%<\/b><small>На людях<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>В тесте из патентного документа: со смываемым очищающим средством с 0,5% цинка PCA кожное сало за 28 дней уменьшилось на 32%. С очищающим средством без актива для контроля жирности снижение составило 25%.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Патентный документ<\/em> CN119896624A, 2025<\/p><p>Смываемое очищающее средство, по 10 человек в группе, 28 дней. В тестовой формуле были и другие активы. Сравнение проводили с очищающим средством без актива для контроля жирности.<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>В тестовой формуле, кроме цинка PCA, есть также никотинамид 3% и масло чайного дерева 0,2%. Для цинка PCA есть данные и по несмываемому крему: с кремом 0,3% кожное сало −43%, с кремом без цинка −39% (CN120053345A).<\/p><\/section><\/div><\/article><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-reborn-pan3\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/e8de229d733b.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для комфорта и увлажнения<\/span><span class=\"ak-ad\" lang=\"en\">Panthenol<\/span><span class=\"ak-o\">На этикетке: 1%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-reborn-pan3\" hidden><p class=\"ak-ac\">В коже превращается в витамин B5. Помогает успокоить кожу и сохранить ее увлажненность.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>1%<\/b><small>сырье · 0,75% в чистом виде<\/small><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>0,3%<\/b><small>На людях<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>В тесте из патентного документа: в формуле с 0,3% пантенола число пор, измеренное на щеке, за 2 недели было примерно на 21% меньше, чем в такой же формуле без пантенола. Размер пор также оценивали визуально. По сравнению с формулой без пантенола балл был примерно на 33% ниже. Более низкий балл означает более мелкие поры.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Патентный документ<\/em> JP2023-154112A, 2023<\/p><p>Каждую формулу, с пантенолом и без, 7 человек использовали 2 недели на коже щек.<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>Оценивали число и размер пор, шелушение и текстуру. Сырье в этом продукте содержит 75% чистого вещества. Исследование проводили с несмываемым продуктом. Reborn+ — смываемое очищающее средство.<\/p><\/section><\/div><\/article><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-reborn-bot\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/6a1ed71911d2.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для успокоения<\/span><span class=\"ak-ad\" lang=\"en\">7 Botanical Complex®<\/span><span class=\"ak-o\">На этикетке: 1%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-reborn-bot\" hidden><p class=\"ak-ac\">Успокаивающая смесь из семи растений. Есть во всех наших сыворотках, тониках и очищающих средствах.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>1%<\/b><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>1%<\/b><small>Тест на клетках<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>В лаборатории, в чашке с клетками: 7 Botanical Complex тестировали в концентрации 1%. В иммунных клетках человека, подвергнутых стрессу, три сигнала стресса снизились примерно на 41–54% по сравнению с клетками без комплекса.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Тест производителя<\/em> Clariant, презентация MultiEx BSASM, 2023<\/p><p>Иммунные клетки человека подвергли стрессу и обработали комплексом. Измеряли: три сигнала стресса.<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>Моноциты человека THP-1, стресс LPS. При 1%: IL-8 примерно −43%, TNF-α примерно −41%, NF-κB примерно −54% (презентация производителя, график). Тест проводили в лаборатории. Reborn+ — смываемое очищающее средство.<\/p><\/section><\/div><\/article><\/div><\/section><section class=\"bl\"><h4>4 поддерживающих актива<\/h4><div class=\"ak-iz\"><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-reborn-gt\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/425a710221ba.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для комфорта кожи<\/span><span class=\"ak-ad\" lang=\"en\">Green Tea Extract<\/span><span class=\"ak-o\">На коробке: 0,5%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-reborn-gt\" hidden><p class=\"ak-ac\">Экстракт зеленого чая. Помогает успокоить кожу при очищении.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>0,5%<\/b><small>сырье · 0,053% экстракта<\/small><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>0,005%<\/b><small>экстракт · ферментный тест<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>В лаборатории, в бесклеточном тесте: с 0,005% экстракта зеленого чая активность фермента, нарушающего эластичность кожи, снизилась максимум на 39%, а фермента, образующего пятна, — на 43%.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Научная статья<\/em> <a href=\"https://pubmed.ncbi.nlm.nih.gov/32515615/\" target=\"_blank\" rel=\"noopener\">Lianza и соавт., J Enzyme Inhib Med Chem, 2020<\/a><\/p><p>90 растительных продуктов тестировали в бесклеточном ферментном тесте. Экстракт зеленого чая давали в концентрации 0,005% (50 мкг/мл).<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>Ингибирование эластазы и тирозиназы, бесклеточный тест. Тест проводили в лаборатории. Reborn+ — смываемое очищающее средство.<\/p><\/section><\/div><\/article><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-reborn-all\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/9d18fa4f8ecb.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для комфорта кожи<\/span><span class=\"ak-ad\" lang=\"en\">Allantoin<\/span><span class=\"ak-o\">На коробке: 0,2%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-reborn-all\" hidden><p class=\"ak-ac\">Помогает успокоить и смягчить кожу.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>0,2%<\/b><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>0,01%<\/b><small>Тест на клетках<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>В лаборатории, в чашке с клетками: в клетках кожи человека, стимулированных молочной кислотой и получивших 0,01% аллантоина, снизилась активность одного гена стресса.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Научная статья<\/em> <a href=\"https://pubmed.ncbi.nlm.nih.gov/42352310/\" target=\"_blank\" rel=\"noopener\">Kim и соавт., Biomolecules, 2026<\/a><\/p><p>Использовали клетки кожи человека, стимулированные молочной кислотой. Аллантоин давали в концентрации 0,01% (100 мкг/мл).<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>Модель HaCaT и фибробластов человека. Экспрессию гена PTGS2 измеряли методом qRT-PCR. Тест проводили в лаборатории. Reborn+ — смываемое очищающее средство.<\/p><\/section><\/div><\/article><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-reborn-kak\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/070cfd2a5d2e.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для живого вида<\/span><span class=\"ak-ad\" lang=\"en\">Kakadu Plum Extract<\/span><span class=\"ak-o\">На коробке: 0,1%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-reborn-kak\" hidden><p class=\"ak-ac\">Экстракт сливы какаду. Этот плод богат витамином C. Помогает придать коже живой вид.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>0,1%<\/b><small>сырье · 0,01% экстракта<\/small><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>0,01%<\/b><small>очищенный · тест на клетках<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>В лаборатории, на клеточной линии мышиного происхождения: 0,01% очищенного экстракта какаду снизил два показателя стресса.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Научная статья<\/em> Tan и соавт., 2011; цит. по Kapini и соавт., Biomedicines, 2025<\/p><p>Клеточную линию стимулировали веществом-стимулятором (LPS). Давали полифенол, очищенный из сливы какаду.<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>Клетки RAW 264.7. Измеряли нитрат и нитрит, а также простагландин E2. Тест проводили в лаборатории. Reborn+ — смываемое очищающее средство.<\/p><\/section><\/div><\/article><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-reborn-tt\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/11181d15370e.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для ощущения чистоты<\/span><span class=\"ak-ad\" lang=\"en\">Tea Tree Extract<\/span><span class=\"ak-o\">На коробке: 0,05%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-reborn-tt\" hidden><p class=\"ak-ac\">Получают из чайного дерева. При очищении дает коже ощущение чистоты.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>0,05%<\/b><small>сырье<\/small><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>0,0025%<\/b><small>часть · на людях, выделенная часть<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>В тесте из патентного документа: вещество, выделенное из чайного дерева, тестировали в концентрации 0,0025%. В группе из 22 человек увлажненность кожи за 28 дней выросла на 12%, шероховатость уменьшилась на 9%. Сравнение проводили с 22 людьми, использовавшими крем без этого вещества.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Патентный документ<\/em> JP2025-510129A, 2025<\/p><p>44 человека разделили на две группы. Крем использовали 28 дней. Измеряли: увлажненность и шероховатость поверхности.<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>Исследованное вещество — фракция, а не цельное масло или экстракт. Результаты приведены по двухфакторному ANOVA. Шероховатость измеряли по показателю Sa. Исследование проводили с несмываемым продуктом. Reborn+ — смываемое очищающее средство.<\/p><\/section><\/div><\/article><\/div><\/section><div class=\"alt-cta\"><a class=\"cta\" href=\"/ru/reborn-plus-temizleme-jeli\">СМОТРЕТЬ ПРОДУКТ<\/a><a class=\"ok\" href=\"#sec\">Посмотреть другую проблему<\/a><\/div><\/div><\/div><\/section><section class=\"panel\" id=\"p-pore\" role=\"tabpanel\" aria-labelledby=\"t-pore\" style=\"--k:#33302D\"><div class=\"ic pn\"><div class=\"ur\"><img class=\"ur-g\" loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/570a09f0c7ec.jpg\" alt=\"Pore Reset+ Toner\"><div class=\"ur-m\"><p class=\"tag\">Поры, текстура и матовость<\/p><h3>Pore Reset+ Toner<\/h3><p class=\"bic\">Тоник · 200 мл<\/p><\/div><p class=\"fay\">Помогает очищать поры. Помогает текстуре кожи выглядеть более гладкой и матовой.<\/p><a class=\"cta\" href=\"/ru/pore-reset-plus-tonik\">СМОТРЕТЬ ПРОДУКТ<\/a><\/div><div class=\"ic-bl\"><section class=\"kt\"><p class=\"kt-u\">СОБСТВЕННЫЙ ТЕСТ ЭТОГО ПРОДУКТА<\/p><b>Не раздражает в тесте<\/b><p>В 48-часовом дерматологическом тесте с добровольцами с чувствительной кожей этот продукт вошел в класс «не раздражающий».<\/p><p>Продукт также прошел анализы на микробиологическое качество, защиту формулы от микробов, стабильность и тяжелые металлы.<\/p><p class=\"kay\"><em>Лабораторный отчет<\/em> SKINLAB, Краков · <a href=\"/ru/pages/test-sonuclarimiz\">Смотреть результаты тестов<\/a><\/p><\/section><section class=\"bl\"><h4>4 ключевых актива<\/h4><p class=\"ipucu\">Нажми на актив. Здесь откроются результат, измеренный в исследовании, источник и техническая заметка. Исследования проводились с самим активом, а не с этим продуктом.<\/p><div class=\"ak-iz\"><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-pore-sal\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/521be9e4e44c.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для пор<\/span><span class=\"ak-ad\" lang=\"en\">Salicylic Acid (BHA)<\/span><span class=\"ak-o\">На этикетке: 2%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-pore-sal\" hidden><p class=\"ak-ac\">Жирорастворимая кислота (BHA), поэтому она может проникать внутрь поры. Помогает порам выглядеть менее заметными.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>2%<\/b><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>0,5%<\/b><small>На людях<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>В группе, использовавшей пэды с 0,5% салициловой кислоты, число высыпаний за 12 недель уменьшилось на 38,4%. В группе с пэдами, пропитанными водой со стабилизированной кислотностью (буферная вода), снижение составило 24,6%.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Научная статья<\/em> <a href=\"https://pubmed.ncbi.nlm.nih.gov/6458457/\" target=\"_blank\" rel=\"noopener\">Shalita, Cutis, 1981<\/a><\/p><p>49 человек разделили на две группы. Исследование длилось 12 недель. Измеряли: число высыпаний.<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>Активная группа n=25, пэд на спиртовой основе; контроль — буферная вода. Данные приводятся в обзоре Cochrane (Liu 2020).<\/p><\/section><\/div><\/article><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-pore-pha1\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/69afeee4d496.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для мягкого обновления поверхности<\/span><span class=\"ak-ad\" lang=\"en\">Gluconolactone (PHA)<\/span><span class=\"ak-o\">На этикетке: 1%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-pore-pha1\" hidden><p class=\"ak-ac\">Кислота (PHA), которая мягко обновляет поверхность кожи. Ее молекула крупная, поэтому она работает в основном на поверхности.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>1%<\/b><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>1%<\/b><small>На людях<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>В тесте из патентного документа: 10 экспертов-оценщиков 1 неделю использовали две жидкости и оценивали кожу. Для жидкости с 1% глюконолактона (PHA) сообщалось о положительном изменении шероховатости кожи. Для жидкости без глюконолактона такого изменения не наблюдалось.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Патентный документ<\/em> JP2026-141151A, 2026<\/p><p>10 экспертов-оценщиков 1 неделю использовали две жидкости и сравнивали их. Измеряли: шероховатость кожи.<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>Сенсорная оценка. Жидкость с активом pH 3,6, основа pH 3,8.<\/p><\/section><\/div><\/article><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-pore-car\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/1cce800898a9.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для баланса жирности<\/span><span class=\"ak-ad\" lang=\"en\">L-Carnitine<\/span><span class=\"ak-o\">На этикетке: 0,5%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-pore-car\" hidden><p class=\"ak-ac\">Вещество, производное аминокислоты. Поддерживает баланс жирности кожи.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>0,5%<\/b><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>0,5%<\/b><small>На людях<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>Кожу окрасили. На участке, на который ничего не наносили, краска бледнела наполовину примерно 10 дней. На участке, где наносили раствор 0,5% L-карнитина, — примерно 8,8 дня. Чем короче срок, тем быстрее измеренное обновление поверхности.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Научная статья<\/em> <a href=\"https://pubmed.ncbi.nlm.nih.gov/31534155/\" target=\"_blank\" rel=\"noopener\">In и соавт., Sci Rep, 2019<\/a><\/p><p>15 добровольцев, 20-40 лет, внутренняя сторона плеча. Кожу окрасили и отслеживали, за какое время бледнеет краска.<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>Водный раствор. Время обновления кожи измеряли методом окрашивания DHA.<\/p><\/section><\/div><\/article><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-pore-bot\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/6a1ed71911d2.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для успокоения<\/span><span class=\"ak-ad\" lang=\"en\">7 Botanical Complex®<\/span><span class=\"ak-o\">На этикетке: 1%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-pore-bot\" hidden><p class=\"ak-ac\">Успокаивающая смесь из семи растений. Есть во всех наших сыворотках, тониках и очищающих средствах.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>1%<\/b><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>1%<\/b><small>Тест на клетках<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>В лаборатории, в чашке с клетками: 7 Botanical Complex тестировали в концентрации 1%. В иммунных клетках человека, подвергнутых стрессу, три сигнала стресса снизились примерно на 41–54% по сравнению с клетками без комплекса.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Тест производителя<\/em> Clariant, презентация MultiEx BSASM, 2023<\/p><p>Иммунные клетки человека подвергли стрессу и обработали комплексом. Измеряли: три сигнала стресса.<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>Моноциты человека THP-1, стресс LPS. При 1%: IL-8 примерно −43%, TNF-α примерно −41%, NF-κB примерно −54% (презентация производителя, график).<\/p><\/section><\/div><\/article><\/div><\/section><section class=\"bl\"><h4>4 поддерживающих актива<\/h4><div class=\"ak-iz\"><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-pore-nia1\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/e146040b7101.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для барьера и баланса жирности<\/span><span class=\"ak-ad\" lang=\"en\">Niacinamide<\/span><span class=\"ak-o\">На коробке: 1%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-pore-nia1\" hidden><p class=\"ak-ac\">Витамин B3. Поддерживает защитный внешний слой кожи (барьер) и баланс жирности.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>1%<\/b><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>1%<\/b><small>На людях<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>В группе, использовавшей гель с 1% ниацинамида, число шероховатых участков на коже, поврежденной солнцем, за 3 месяца уменьшилось на 21,8%. С гелем без этого вещества снижение составило 10%. Исследование проводили у людей с повреждением кожи от солнца.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Научная статья<\/em> <a href=\"https://pubmed.ncbi.nlm.nih.gov/20199551/\" target=\"_blank\" rel=\"noopener\">Moloney и соавт., Br J Dermatol, 2010<\/a><\/p><p>30 человек случайным образом разделили на группы. Ни добровольцы, ни исследователи не знали, кто каким гелем пользуется. Гель наносили 2 раза в день.<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>Число очагов на коже, поврежденной солнцем, дизайн с контролем неактивным продуктом. 1% никотинамида, исследование на 6 месяцев; результат — измерение на 3-м месяце. Название диагноза указано в исходной статье.<\/p><\/section><\/div><\/article><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-pore-pan03\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/e8de229d733b.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для комфорта и увлажнения<\/span><span class=\"ak-ad\" lang=\"en\">Panthenol<\/span><span class=\"ak-o\">На коробке: 0,3%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-pore-pan03\" hidden><p class=\"ak-ac\">В коже превращается в витамин B5. Помогает успокоить кожу и сохранить ее увлажненность.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>0,3%<\/b><small>сырье · 0,225% в чистом виде<\/small><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>0,03%<\/b><small>На людях<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>В тесте из патентного документа: в формуле с 0,03% пантенола число пор, измеренное на щеке, за 2 недели было примерно на 28% меньше, чем в такой же формуле без пантенола.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Патентный документ<\/em> JP2023-154112A, 2023<\/p><p>Каждую формулу, с пантенолом и без, 7 человек использовали 2 недели на коже щек.<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>Оценивали число и размер пор, шелушение и текстуру. В этом продукте сырье содержит 75% чистого вещества: 0,3% сырья, 0,225% чистого пантенола.<\/p><\/section><\/div><\/article><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-pore-zn\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/621c2bea3751.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для баланса жирности и матового вида<\/span><span class=\"ak-ad\" lang=\"en\">Zinc PCA<\/span><span class=\"ak-o\">На коробке: 0,2%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-pore-zn\" hidden><p class=\"ak-ac\">Поддерживает баланс жирности кожи. Помогает коже выглядеть более матовой.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>0,2%<\/b><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>0,1875%<\/b><small>Тест на культуре<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>В лаборатории, в чашке: в тесте производителя минимальная концентрация цинка PCA, останавливающая рост бактерии, живущей на коже (C. acnes), составила 0,1875%. Тест проводили не на коже.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Тест производителя<\/em> Ajinomoto, брошюра AJIDEW ZN-100<\/p><p>Бактерию выращивали в чашке. Измеряли минимальную концентрацию, останавливающую рост.<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>MIC (тест в чашке): C. acnes 1875 мкг/мл, S. aureus 938 мкг/мл, Malassezia 313 мкг/мл.<\/p><\/section><\/div><\/article><article class=\"ak\"><button type=\"button\" class=\"ak-b\" aria-expanded=\"false\" aria-controls=\"d-pore-all\"><span class=\"ak-g\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/9d18fa4f8ecb.jpg\" alt=\"\" loading=\"lazy\"><\/span><span class=\"ak-f\">Для комфорта кожи<\/span><span class=\"ak-ad\" lang=\"en\">Allantoin<\/span><span class=\"ak-o\">На коробке: 0,1%<\/span><span class=\"ak-t\">Исследование и результат<\/span><\/button><div class=\"ak-d\" id=\"d-pore-all\" hidden><p class=\"ak-ac\">Помогает успокоить и смягчить кожу.<\/p><div class=\"ak-or\"><div><span>В ЭТОМ ПРОДУКТЕ<\/span><b>0,1%<\/b><\/div><div><span>В ИССЛЕДОВАНИИ<\/span><b>0,01%<\/b><small>Тест на клетках<\/small><\/div><\/div><section class=\"z\"><h6>РЕЗУЛЬТАТ, ИЗМЕРЕННЫЙ В ИССЛЕДОВАНИИ<\/h6><p>В лаборатории, в чашке с клетками: в клетках кожи человека, стимулированных молочной кислотой и получивших 0,01% аллантоина, снизилась активность одного гена стресса.<\/p><\/section><section class=\"z\"><h6>ИСТОЧНИК (ИССЛЕДОВАНИЕ АКТИВА)<\/h6><div class=\"z-k\"><div><p class=\"z-a\"><em>Научная статья<\/em> <a href=\"https://pubmed.ncbi.nlm.nih.gov/42352310/\" target=\"_blank\" rel=\"noopener\">Kim и соавт., Biomolecules, 2026<\/a><\/p><p>Использовали клетки кожи человека, стимулированные молочной кислотой. Аллантоин давали в концентрации 0,01% (100 мкг/мл).<\/p><\/div><\/div><\/section><section class=\"z z-u\"><h6>ТЕХНИЧЕСКАЯ ЗАМЕТКА ДЛЯ ФАРМАЦЕВТА И ДЕРМАТОЛОГА<\/h6><p>Модель HaCaT и фибробластов человека. Экспрессию гена PTGS2 измеряли методом qRT-PCR.<\/p><\/section><\/div><\/article><\/div><\/section><div class=\"alt-cta\"><a class=\"cta\" href=\"/ru/pore-reset-plus-tonik\">СМОТРЕТЬ ПРОДУКТ<\/a><a class=\"ok\" href=\"#sec\">Посмотреть другую проблему<\/a><\/div><\/div><\/div><\/section>\n<section class=\"bant\"><div class=\"ic r7\"><img loading=\"lazy\" decoding=\"async\" src=\"https://cagrikirte.github.io/tsp-kanit/aktifler/gorsel/cc4b165feed9.png\" alt=\"Respect 7\">\n<div><h2>7 правил наших формул.<\/h2><ul><li>Без отдушек<\/li><li>Без сушащего спирта<\/li><li>Без химических фильтров<\/li><li>Без красителей<\/li><li>Без эфирных масел<\/li><li>Без силиконов<\/li><li>Без SLS<\/li><\/ul><a class=\"ok\" href=\"/ru/pages/respect-7\">Смотреть список Respect 7<\/a><\/div><\/div><\/section>\n<section class=\"bant sss\"><div class=\"ic\"><h2>Частые вопросы<\/h2><div class=\"sg\"><div><h3>Что значит «На этикетке: 5%»?<\/h3><p>Это доля, в которой актив входит в формулу. Некоторые активы входят в формулу в виде раствора или смеси. Тогда процент — это доля раствора или смеси. Проценты 4 ключевых активов указаны на флаконе и на коробке. Проценты поддерживающих активов указаны только на коробке.<\/p><\/div><div><h3>Исследования проводились с этим продуктом?<\/h3><p>С самим активом. Когда нажимаешь на актив, видишь рядом процент в исследовании и процент в этом продукте. Собственные тесты наших продуктов — на странице «Результаты наших тестов».<\/p><\/div><div><h3>Чем отличаются научная статья, тест производителя и патентный документ?<\/h3><p>Научную статью до публикации проверяют независимые эксперты. Тест производителя проводит компания, которая производит этот актив. Эта компания может не быть нашим поставщиком. Тест из патентного документа проводит компания, подавшая заявку. Какой это тип, указано в разделе, который открывается при нажатии на актив.<\/p><\/div><div><h3>Эти продукты лечат заболевания?<\/h3><p>Нет. Наши продукты — косметика. Если проблема с кожей не проходит, обратись к дерматологу.<\/p><\/div><\/div><\/div><\/section>\n<section class=\"son\"><div class=\"ic\"><h2>Не нужно быть химиком.<\/h2><p>Для каждой проблемы мы подготовили свой продукт. Тебе остается выбрать свою проблему.<\/p>\n<a class=\"cta\" href=\"/ru/pages/cilt-problemi\">ВЫБЕРИ ПО ПРОБЛЕМЕ КОЖИ<\/a>\n<div class=\"son-l\"><a class=\"ok\" href=\"/ru/pages/kutuphane\">Библиотека<\/a><a class=\"ok\" href=\"/ru/pages/test-sonuclarimiz\">Результаты наших тестов<\/a><\/div><\/div><\/section>\n<\/div>\n<div class=\"dip\"><div class=\"ic\">Наши продукты — косметика, они не предназначены для лечения заболеваний.<\/div><\/div>";
  var K, son = 0;
  function sec(k, kaydir, yaz) {
    var t = [].slice.call(K.querySelectorAll('[role=tab]'));
    t.forEach(function (b) { var s = b.dataset.k === k; b.setAttribute('aria-selected', s); b.tabIndex = s ? 0 : -1; K.querySelector('#p-' + b.dataset.k).hidden = !s; });
    if (kaydir) { var p = K.querySelector('#p-' + k); if (p.getBoundingClientRect().top < ust()) p.scrollIntoView(); }
    if (yaz) { try { history.replaceState(history.state, '', '#' + k); } catch (e) {} }
  }
  // Tema üst bandının yüksekliği: yapışkan seçim çubuğu ve kaydırma payı buna göre iner
  function ust() {
    // Kaydırılınca tema ayrı sabit bir bant (div.sticky) gösterir; o yoksa header'ın altı, ikisi de ölçülemezse son değer
    var s = document.querySelector('div.sticky'), h = document.querySelector('header'), y = 0;
    if (s && s.offsetHeight && getComputedStyle(s).position === 'fixed') y = Math.round(s.getBoundingClientRect().bottom);
    if (!y && h) y = Math.max(0, Math.round(h.getBoundingClientRect().bottom));
    if (y) son = y; else y = son;
    if (K) K.style.setProperty('--ust', y + 'px');
    return y;
  }
  function gecerli(h) { return !!K.querySelector('[role=tab][data-k="' + h.replace(/[^a-z]/g, '') + '"]') && /^[a-z]+$/.test(h); }
  function kur(kok) {
    if (!kok || kok.dataset.kuruldu) return;
    kok.dataset.kuruldu = '1';
    K = kok;
    kok.innerHTML = HTML;
    var t = [].slice.call(kok.querySelectorAll('[role=tab]'));
    t.forEach(function (b, i) {
      b.addEventListener('click', function () { sec(b.dataset.k, true, true); });
      b.addEventListener('keydown', function (e) {
        var d = e.key === 'ArrowRight' ? 1 : e.key === 'ArrowLeft' ? -1 : 0; if (!d) return;
        e.preventDefault(); var n = t[(i + d + t.length) % t.length]; sec(n.dataset.k, false, true); n.focus();
      });
    });
    [].forEach.call(kok.querySelectorAll('.ak-b'), function (b) {
      b.addEventListener('click', function () {
        var k = b.parentNode, ac = !k.classList.contains('ak-acik');
        [].forEach.call(kok.querySelectorAll('.ak-acik'), function (y) { y.classList.remove('ak-acik'); y.querySelector('.ak-b').setAttribute('aria-expanded', 'false'); y.querySelector('.ak-d').hidden = true; });
        if (ac) { k.classList.add('ak-acik'); b.setAttribute('aria-expanded', 'true'); k.querySelector('.ak-d').hidden = false; }
        // Kartın üstü sabit bandın altında kalmasın: yalnız görünmüyorsa kaydırılır
        var u = ust(), y = k.getBoundingClientRect().top;
        if (y < u + 8 || y > innerHeight - 120) window.scrollBy(0, y - u - 12);
      });
    });
    var h = location.hash.slice(1);
    ust();
    sec(gecerli(h) ? h : t[0].dataset.k, gecerli(h), false);
  }
  window.addEventListener('hashchange', function () { if (K && K.isConnected) { var h = location.hash.slice(1); if (gecerli(h)) sec(h, true, false); } });
  window.addEventListener('resize', function () { if (K && K.isConnected) ust(); });
  window.addEventListener('scroll', function () { if (K && K.isConnected) ust(); }, { passive: true });
  // Site içi geçişlerde sayfa yenilenmez: Script her dönüşte kur'u yeniden çağırır.
  window.TSP_AKT = { kur: kur, L: "ru" };
  kur(document.getElementById('tsp-aktifler'));
})();
